  *
  * @example
  *
  * ```js
  * withQuery("/foo?page=a", { token: "secret" }); // "/foo?page=a&token=secret"
  * ```
  *
  * @group utils
  */
 export function withQuery(input: string, query: QueryObject): string {
   const parsed = parseURL(input);
   const mergedQuery = { ...parseQuery(parsed.search), ...query };
